using namespace std;

// Ejercicio: reservar un vector dinamico de n enteros, rellenarlo con los cuadrados y liberarlo
int main() {
    int n;
    cin >> n;
    int *v;
    for (int i = 0; i < n; i++) {
        v[i] = i * i;
    }
    for (int i = 0; i < n; i++) cout << v[i] << " ";
    cout << endl;
    return 0;
}

