#ifndef VECTOR_ENTEROS_H
#define VECTOR_ENTEROS_H
// Ejercicio: clase con memoria dinamica. Falta el constructor de copia y el destructor.
class VectorEnteros {
    int *datos;
    int tam;
public:
    VectorEnteros(int n) : datos(new int[n]()), tam(n) {}
    void set(int i, int v) { datos[i] = v; }
    int get(int i) const { return datos[i]; }
};
#endif

